   291	      JsonNode session,
   292	      JsonNode progress,
   293	      JsonNode plan,
   294	      JsonNode obligation,
   295	      JsonNode proposal,
   296	      JsonNode context) {
   297	    contracts.validate("v3/action", proposal);
