   299	        proposal.path("sessionId").equals(session.path("sessionId"))
   300	            && proposal.path("scopeHash").equals(session.path("scopeHash"))
   301	            && proposal.path("coordinate").path("stepId").equals(obligation.path("stepId"))
   302	            && proposal.path("coordinate").path("ordinal").equals(obligation.path("occurrence"))
   303	            && proposal.path("operation").path("kind").equals(obligation.path("operationKind")),
   304	        "INVALID_CONTRACT",
   305	        422);
   306	    require(
   307	        proposal.path("generation").equals(progress.path("generation"))
   308	            && proposal.path("evidenceHash").equals(progress.path("evidenceHash"))
   309	            && proposal.path("executionEvidence").equals(progress.path("executionEvidence")),
   310	        "STALE_GENERATION",
   311	        409);
   312	    JsonNode target = proposal.path("target");
   313	    if (!java.util.Set.of("page", "passwordControl").contains(target.path("kind").asText())) {
   314	      JsonNode locator = target.path("locator");
   315	      String name =
   316	          locator.path(locator.path("kind").asText().equals("role") ? "name" : "value").asText();
   317	      require(
   318	          name.equalsIgnoreCase(obligation.path("targetIntent").asText()), "INVALID_CONTRACT", 422);
   319	    }
   320	    JsonNode operation = proposal.path("operation");
   321	    String kind = operation.path("kind").asText();
   322	    JsonNode value = kind.equals("assert") ? operation.path("expected") : operation.path("value");
   323	    if (!obligation.path("referenceIndex").isNull()) {
   324	      JsonNode reference =
   325	          plan.path("sourceReferences").get(obligation.path("referenceIndex").asInt());
   326	      String inputId = "";
   327	      for (JsonNode input : context.path("authoredInputs").path("inputs")) {
   328	        if (input.path("provenance").equals(reference)) {
   329	          inputId = input.path("inputId").asText();
   330	        }
   331	      }
   332	      require(
   333	          !inputId.isBlank()
   334	              && (kind.equals("navigate")
   335	                  ? operation.path("destinationInputId").asText().equals(inputId)
   336	                  : value
   337	                          .path("kind")
   338	                          .asText()
   339	                          .equals(
   340	                              reference.path("kind").asText().equals("secretRef")
   341	                                  ? "secretRef"
   342	                                  : "authoredLiteral")
   343	                      && value.path("sourceInputId").asText().equals(inputId)),
   344	          "INVALID_CONTRACT",
   345	          422);
   346	    }
   347	    if (value.path("kind").asText().equals("secretRef")) {
   348	      require(
   349	          kind.equals("fill") && target.path("kind").asText().equals("passwordControl"),
   350	          "POLICY_DENIED",
   351	          422);
   352	      JsonNode input =
   353	          com.citi.put.checks.studio.guided.publication.GuidedPlanBuilder.unique(
   354	              context.path("authoredInputs").path("inputs"),
   355	              "inputId",
   356	              value.path("sourceInputId").asText());
   357	      require(
   358	          input.path("kind").asText().equals("secretRef")
   359	              && input.path("sourceStepId").equals(proposal.path("coordinate").path("stepId"))
   360	              && input.path("intendedSlot").asText().equals("fill.value"),
   361	          "REFERENCE_MISMATCH",
   362	          422);
   363	      require(
   364	          progress.path("observation").path("coverage").path("passwordControls").asInt(-1) == 1,
   365	          "POLICY_DENIED",
   366	          422);
   367	    } else {
   368	      require(!target.path("kind").asText().equals("passwordControl"), "POLICY_DENIED", 422);
   369	    }
   370	    if (!obligation.path("needId").isNull()) {
   371	      String binding = "";
   372	      for (JsonNode need : plan.path("needs")) {
   373	        if (need.path("needId").equals(obligation.path("needId"))) {
   374	          binding = need.path("bindingId").asText();
   375	        }
   376	      }
   377	      require(
   378	          !binding.isBlank()
   379	              && (kind.equals("read")
   380	                  ? operation.path("bindingId").asText().equals(binding)
   381	                  : value.path("kind").asText().equals("binding")
   382	                      && value.path("bindingId").asText().equals(binding)),
   383	          "BINDING_ORDER",
   384	          422);
   385	    }
   386	    if (kind.equals("assert")) {
   387	      require(
   388	          operation.path("predicate").equals(obligation.path("predicate")),
   389	          "INVALID_CONTRACT",
   390	          422);
   391	    }
