4193	  private static void p3CaptureOrdinaryReport(UUID execution, byte[] bytes) {
4194	    int phase = 1;
4195	    try {
4196	      if (bytes.length > 262144) {
4197	        throw new IllegalArgumentException("P3 callback witness bound");
4198	      }
4199	      String text =
4200	          StandardCharsets.UTF_8
4201	              .newDecoder()
4202	              .onMalformedInput(java.nio.charset.CodingErrorAction.REPORT)
4203	              .onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT)
4204	              .decode(java.nio.ByteBuffer.wrap(bytes))
4205	              .toString();
4206	      phase = 2;
4207	      // Strict duplicates/trailing tokens remain; ordinary timing numbers are not canonical-v1
4208	      // integers.
4209	      JsonNode actual = C.parse(text);
4210	      long[] numeric = p3ReportNumericCounts(actual, 0);
4211	      phase = 3;
4212	      new com.citi.put.checks.studio.internal.StrictInternalBodyReader(JSON)
4213	          .read(bytes, com.citi.put.checks.studio.internal.dto.RunnerReport.class);
4214	      boolean finalReport = actual.path("kind").asText().equals("FINAL");
4215	      P3_CAPTURE_DIAGNOSTICS.compute(
4216	          execution,
4217	          (id, previous) -> {
4218	            ObjectNode metrics = previous == null ? C.object() : previous.deepCopy();
4219	            metrics.put("captureSuccesses", metrics.path("captureSuccesses").asLong() + 1);
4220	            if (finalReport) {
4221	              metrics
4222	                  .put("finalSuccesses", metrics.path("finalSuccesses").asLong() + 1)
4223	                  .put("finalBytes", bytes.length)
4224	                  .put("finalFloatLexemes", numeric[0])
4225	                  .put("finalFractionalValues", numeric[1])
4226	                  .put("guidedIntegerParserWouldRefuse", numeric[0] > 0);
4227	            }
4228	            return metrics;
4229	          });
4230	      if (finalReport) {
4231	        P3_FINAL_REPORTS.put(execution, actual);
4232	      }
4233	    } catch (Exception failure) {
4234	      final int failedPhase = phase;
4235	      P3_CAPTURE_DIAGNOSTICS.compute(
4236	          execution,
4237	          (id, previous) -> {
4238	            ObjectNode metrics = previous == null ? C.object() : previous.deepCopy();
4239	            return metrics
