4248	  private static long[] p3ReportNumericCounts(JsonNode node, int depth) {
4249	    int structuralDepth = depth + (node.isContainerNode() ? 1 : 0);
4250	    if (structuralDepth > 64) {
4251	      throw new IllegalArgumentException("P3 callback witness depth");
4252	    }
4253	    long floats = 0, fractions = 0;
4254	    if (node.isNumber()) {
4255	      double number = node.doubleValue();
4256	      if (!Double.isFinite(number)) {
4257	        throw new IllegalArgumentException("P3 nonfinite callback number");
4258	      }
4259	      if (node.isFloatingPointNumber()) {
4260	        floats = 1;
4261	        fractions = number != Math.rint(number) ? 1 : 0;
4262	      }
4263	    }
4264	    if (node.isContainerNode()) {
4265	      for (JsonNode child : node) {
4266	        long[] counts = p3ReportNumericCounts(child, structuralDepth);
4267	        floats += counts[0];
4268	        fractions += counts[1];
4269	      }
4270	    }
4271	    return new long[] {floats, fractions};
4272	  }
