4294	  private JsonNode p3CleanupSnapshot(UUID execution, String cookie, long deadline)
4295	      throws Exception {
4296	    for (; ; ) {
4297	      long now = System.nanoTime();
4298	      long delay = Math.max(0, p3NextCleanupGetAt - now);
4299	      long remaining = deadline - now;
4300	      if (remaining <= delay) {
4301	        throw new IllegalStateException("Actual ordinary cleanup wait exceeds deadline");
4302	      }
4303	      if (delay > 0) {
4304	        java.util.concurrent.TimeUnit.NANOSECONDS.sleep(delay);
4305	      }
4306	      long requestStarted = System.nanoTime();
4307	      p3NextCleanupGetAt = requestStarted + Duration.ofSeconds(1).toNanos();
4308	      var request =
4309	          HttpRequest.newBuilder(
4310	                  URI.create(
4311	                      "https://localhost:" + port + "/api/v1/studio/executions/" + execution))
4312	              .timeout(p3CleanupRequestTimeout(deadline))
4313	              .header("Cookie", "put_session=" + cookie)
4314	              .GET()
4315	              .build();
4316	      var response =
4317	          HttpClient.newBuilder()
4318	              .sslContext(TLS)
4319	              .build()
4320	              .send(request, HttpResponse.BodyHandlers.ofString());
4321	      if (response.statusCode() == 429) {
4322	        assertThat(C.parse(response.body()).path("error").path("code").asText())
4323	            .isEqualTo("RATE_LIMITED");
4324	        String actualRetry =
4325	            response
4326	                .headers()
4327	                .firstValue("Retry-After")
4328	                .orElseThrow(
4329	                    () -> new IllegalStateException("Actual rate response lacks Retry-After"));
4330	        assertThat(actualRetry.matches("[1-9][0-9]{0,8}")).isTrue();
4331	        long seconds = Long.parseLong(actualRetry);
4332	        long retryNanos = Duration.ofSeconds(seconds).toNanos();
4333	        now = System.nanoTime();
4334	        if (retryNanos >= deadline - now) {
4335	          throw new IllegalStateException("Actual Retry-After exceeds cleanup deadline");
4336	        }
4337	        p3NextCleanupGetAt = Math.max(p3NextCleanupGetAt, now + retryNanos);
4338	        continue;
4339	      }
4340	      assertThat(response.statusCode())
4341	          .as("actual bounded ordinary cleanup snapshot")
4342	          .isEqualTo(200);
4343	      if (System.nanoTime() >= deadline) {
4344	        throw new IllegalStateException("Actual cleanup response arrived past deadline");
4345	      }
4346	      return C.parse(response.body());
4347	    }
4348	  }
