4350	  private void p3CleanupOwnedResources() throws Exception {
4351	    var failures = new java.util.ArrayList<Throwable>();
4352	    long ordinaryDeadline = System.nanoTime() + Duration.ofSeconds(60).toNanos();
4353	    p3NextCleanupGetAt = System.nanoTime();
4354	    for (var owned : new java.util.ArrayList<>(p3OwnedOrdinaryCookies.entrySet())) {
4355	      try {
4356	        p3CleanupOrdinary(owned.getKey(), owned.getValue(), ordinaryDeadline);
4357	      } catch (Exception | AssertionError failure) {
4358	        failures.add(failure);
4359	      } finally {
4360	        try {
4361	          p3WriteCaptureDiagnostics(owned.getKey());
4362	        } catch (Exception | AssertionError diagnosticsFailure) {
4363	          failures.add(diagnosticsFailure);
4364	        }
4365	      }
4366	    }
4367	    for (var owned : new java.util.ArrayList<>(p3OwnedGuidedCookies.entrySet())) {
4368	      try {
4369	        String id = owned.getKey();
4370	        String state =
4371	            sessions.transaction(() -> sessions.lock(id).document().path("state").asText());
4372	        if (!List.of(
4373	                "SUCCEEDED",
4374	                "PUBLICATION_CONFLICT",
4375	                "FAILED",
4376	                "UNKNOWN_OUTCOME",
4377	                "CANCELLED",
4378	                "EXPIRED")
4379	            .contains(state)) {
4380	          p3Call(
4381	              owned.getValue(),
4382	              "/api/v3/studio/guided-sessions/" + id + "/cancel",
4383	              C.object().put("schemaVersion", 3).put("reason", "userRequested"),
4384	              202);
4385	        }
4386	        p3AwaitTeardown(id);
4387	      } catch (Exception | AssertionError failure) {
4388	        failures.add(failure);
4389	      }
4390	    }
4391	    if (!failures.isEmpty()) {
4392	      var unconfirmed = new IllegalStateException("Actual owned P3 cleanup remains unconfirmed");
4393	      failures.forEach(unconfirmed::addSuppressed);
4394	      throw unconfirmed;
4395	    }
4396	  }
