                      .get(current.progress().path("stepIndex").asInt())
                      .path("stepId")
                      .asText();
              List<ObjectNode> actions =
                  repository.actions(id).stream()
                      .filter(
                          action ->
                              action.path("coordinate").path("stepId").asText().equals(stepId))
                      .toList();
              return new GuidedStepVerifier(store)
