    var matcher = java.util.regex.Pattern.compile("<secret\\s+[A-Za-z0-9_.-]{1,64}>").matcher(text);
    var safe = new StringBuilder(text);
    while (matcher.find()) {
      for (int i = matcher.start(); i < matcher.end(); i++) {
        safe.setCharAt(i, ' ');
      }
    }
    return safe.toString();
  }

